    }

    pub async fn shutdown(&self) -> Result<(), BrowserError> {
        self.browser.shutdown().await
    }

    pub async fn run(&mut self) -> Result<RunResult, AgentError> {
        enum StepControl {
            Continue,
            Done(Action),
        }

        let snapshot_start = Instant::now();
        let mut observation = match self.browser.snapshot().await {
            Ok(observation) => {
                telemetry::record_snapshot_duration(snapshot_start.elapsed());
                observation
            }
            Err(err) => {
                telemetry::record_snapshot_duration(snapshot_start.elapsed());
                tracing::error!(
                    event = "snapshot_error",
                    error_code = err.code,
                    error_message = %err.message
                );
                return Err(AgentError::Browser(err));
            }
        };
        self.memory.record_observation(observation.clone());

        for step_index in 0..self.policy.max_steps {
            let tier = self.router.tier();
            telemetry::inc_step();

            let step_span = tracing::info_span!(
                "step",
                step_index = step_index + 1,
                tier = ?tier,
                url = %observation.url,
                state_hash = ?observation.state_hash
            );

            let step_result = async {
                let step_start = Instant::now();
                let client = self.clients.client(tier);

                let action = match client
                    .propose_action(
                        &self.task,
                        self.memory.plan(),
                        &observation,
                        self.memory.history(),
                    )
                    .await
                {
                    Ok(action) => action,
                    Err(err) => {
                        let duration = step_start.elapsed();
                        telemetry::record_step_duration(duration);
                        tracing::error!(
                            event = "llm_error",
                            error_code = err.code,
                            error_message_len = err.message.chars().count(),
                            step_duration_ms = duration.as_millis() as u64
                        );
                        return Err(AgentError::Llm(err));
                    }
                };

                telemetry::inc_action(&action);
                tracing::info!(
                    event = "action_proposed",
                    action_type = telemetry::action_type(&action),
                    action = ?telemetry::ActionSummary::from(&action)
                );

                if let Err(errors) = self.validator.validate(&action, &observation) {
                    let error_count = errors.len();
                    telemetry::inc_validation_failure();
                    let result = validation_result(errors);
                    self.memory.record_step(action, result);
                    let tier_after = self.router.record(StepOutcome::Failure);
                    telemetry::set_no_progress_streak(self.router.counters().no_progress);
                    let duration = step_start.elapsed();
                    telemetry::record_step_duration(duration);
                    tracing::warn!(
                        event = "validation_failed",
                        error_count = error_count,
                        tier = ?tier_after,
                        step_duration_ms = duration.as_millis() as u64
                    );
                    return Ok(StepControl::Continue);
                }

                if matches!(action, Action::Done { .. }) {
                    let result = done_result(&observation);
                    self.memory.record_step(action.clone(), result);
                    let duration = step_start.elapsed();
                    telemetry::record_step_duration(duration);
                    tracing::info!(
                        event = "done",
                        step_duration_ms = duration.as_millis() as u64
                    );
                    return Ok(StepControl::Done(action));
                }

                let apply_start = Instant::now();
                let result = match self.browser.apply(&action).await {
                    Ok(result) => result,
                    Err(err) => {
                        let apply_duration = apply_start.elapsed();
                        telemetry::record_apply_duration(apply_duration);
                        let duration = step_start.elapsed();
                        telemetry::record_step_duration(duration);
                        tracing::error!(
                            event = "apply_error",
                            error_code = err.code,
                            error_message = %err.message,
                            step_duration_ms = duration.as_millis() as u64
                        );
                        return Err(AgentError::Browser(err));
                    }
                };
                let apply_duration = apply_start.elapsed();
                telemetry::record_apply_duration(apply_duration);
                if !result.ok {
                    telemetry::inc_apply_failure();
                }
                self.memory.record_step(action.clone(), result.clone());

                let snapshot_start = Instant::now();
                let next_observation = match self.browser.snapshot().await {
                    Ok(observation) => observation,
                    Err(err) => {
                        let snapshot_duration = snapshot_start.elapsed();
                        telemetry::record_snapshot_duration(snapshot_duration);
                        let duration = step_start.elapsed();
                        telemetry::record_step_duration(duration);
                        tracing::error!(
                            event = "snapshot_error",
                            error_code = err.code,
                            error_message = %err.message,
                            step_duration_ms = duration.as_millis() as u64
                        );
                        return Err(AgentError::Browser(err));
                    }
                };
                let snapshot_duration = snapshot_start.elapsed();
                telemetry::record_snapshot_duration(snapshot_duration);
                self.memory.record_observation(next_observation.clone());

                let (outcome, heuristics) = step_outcome(&result, &observation, &next_observation);
                let tier_after = self.router.record(outcome);
                telemetry::set_no_progress_streak(self.router.counters().no_progress);

                let error_code = result
                    .error
                    .as_ref()
                    .map(|err| err.code.as_str())
                    .unwrap_or("none");
                let duration = step_start.elapsed();
                telemetry::record_step_duration(duration);
                tracing::info!(
                    event = "step_result",
                    outcome = ?outcome,
                    ok = result.ok,
                    error_code = error_code,
                    tier = ?tier_after,
                    apply_duration_ms = apply_duration.as_millis() as u64,
                    snapshot_duration_ms = snapshot_duration.as_millis() as u64,
                    step_duration_ms = duration.as_millis() as u64,
                    new_state_hash = ?result.new_state_hash,
                    state_hash_unchanged = heuristics.state_hash_unchanged,
                    actionables_unchanged = heuristics.actionables_unchanged,
                    low_actionability = heuristics.low_actionability,
                    prev_actionables = heuristics.prev_actionables,
                    next_actionables = heuristics.next_actionables
                );

                observation = next_observation;
                Ok(StepControl::Continue)
            }
            .instrument(step_span)
            .await?;

            if let StepControl::Done(action) = step_result {
                return Ok(RunResult {
                    status: RunStatus::Done,
                    final_action: action,
                    steps: self.memory.steps().to_vec(),
                    final_observation: observation,
                });
            }
        }

        let final_action = Action::Done {
            summary: "max_steps reached".to_string(),
        };

        Ok(RunResult {
            status: RunStatus::MaxSteps,
            final_action,
            steps: self.memory.steps().to_vec(),
            final_observation: observation,
        })
    }
}

const LOW_ACTIONABILITY_THRESHOLD: usize = 2;

#[derive(Clone, Copy, Debug)]
struct ProgressHeuristics {
    state_hash_unchanged: bool,
    actionables_unchanged: bool,
    low_actionability: bool,
    prev_actionables: usize,
    next_actionables: usize,
}

fn step_outcome(
    result: &StepResult,
    previous: &Observation,
    next: &Observation,
) -> (StepOutcome, ProgressHeuristics) {
    let heuristics = evaluate_progress(previous, next);

    if !result.ok {
        return (StepOutcome::Failure, heuristics);
    }

    let no_progress = heuristics.state_hash_unchanged
        || heuristics.actionables_unchanged
        || heuristics.low_actionability;

    let outcome = if no_progress {
        StepOutcome::NoProgress
    } else {
        StepOutcome::Progress
    };

    (outcome, heuristics)
}

fn evaluate_progress(previous: &Observation, next: &Observation) -> ProgressHeuristics {
    let prev_actionables = previous.elements.len();
    let next_actionables = next.elements.len();
    let state_hash_unchanged = previous.state_hash.is_some() && previous.state_hash == next.state_hash;
    let actionables_unchanged = actionable_signature(previous) == actionable_signature(next);
    let low_actionability = prev_actionables <= LOW_ACTIONABILITY_THRESHOLD
        && next_actionables <= LOW_ACTIONABILITY_THRESHOLD;

    ProgressHeuristics {
        state_hash_unchanged,
        actionables_unchanged,
        low_actionability,
        prev_actionables,
        next_actionables,
    }
}

fn actionable_signature(observation: &Observation) -> Vec<String> {
    let mut ids: Vec<String> = observation
        .elements
        .iter()
        .map(|element| element.id.clone())
        .collect();
    ids.sort();
    ids
}

fn validation_result(errors: Vec<ValidationError>) -> StepResult {
    let message = format_validation_errors(&errors);
    StepResult {
        ok: false,
        error: Some(StepError {
            code: "invalid_action".to_string(),
            message,
        }),
        new_state_hash: None,
        extract: None,
    }
}

fn format_validation_errors(errors: &[ValidationError]) -> String {
    let mut parts = Vec::new();
    for err in errors {
        if let Some(field) = err.field.as_ref() {
            parts.push(format!("{field}: {}", err.message));
        } else {
            parts.push(err.message.clone());
        }
    }
    parts.join("; ")
}

fn done_result(observation: &Observation) -> StepResult {
    StepResult {
        ok: true,
        error: None,
        new_state_hash: observation.state_hash.clone(),
        extract: None,
    }
}

