async fn backend_node_bbox(
    page: &Page,
    backend_node_id: BackendNodeId,
) -> BrowserResult<Option<[f64; 4]>> {
    let model = page
        .execute(
            GetBoxModelParams::builder()
                .backend_node_id(backend_node_id)
                .build(),
        )
        .await?
        .result
        .model;
    Ok(quad_bbox(model.border.inner()))
}

fn quad_bbox(quad: &[f64]) -> Option<[f64; 4]> {
    if quad.len() != 8 {
        return None;
    }
    let xs = [quad[0], quad[2], quad[4], quad[6]];
    let ys = [quad[1], quad[3], quad[5], quad[7]];
    let (min_x, max_x) = xs.iter().fold((xs[0], xs[0]), |acc, x| {
        (acc.0.min(*x), acc.1.max(*x))
    });
    let (min_y, max_y) = ys.iter().fold((ys[0], ys[0]), |acc, y| {
        (acc.0.min(*y), acc.1.max(*y))
    });
    Some([min_x, min_y, max_x - min_x, max_y - min_y])
}

fn stable_signature(role: &str, name: &Option<String>, backend_id: BackendNodeId) -> String {
    let mut parts = Vec::new();
    parts.push("ax".to_string());
    parts.push(role.trim().to_lowercase());
    if let Some(name) = name.as_ref().map(|value| value.trim()).filter(|v| !v.is_empty()) {
        parts.push(name.to_string());
    }
    parts.push(format!("backend={}", backend_id.inner()));
    parts.join("|")
}

fn stable_element_id(signature: &str, occurrence: usize) -> String {
    format!("el_{}_{}", hash_hex(signature), occurrence)
}

fn compute_state_hash(url: &str, title: &str, elements: &[ElementRef]) -> String {
    const TOP_ELEMENTS: usize = 10;
    let mut signature = String::new();
    signature.push_str(url.trim());
    signature.push('\n');
    signature.push_str(title.trim());

    for element in elements.iter().take(TOP_ELEMENTS) {
        signature.push('\n');
        signature.push_str(&element.id);
        signature.push('|');
        signature.push_str(&element.role);
        if let Some(name) = element.name.as_ref() {
            signature.push('|');
            signature.push_str(name);
        }
    }

    hash_hex(&signature)
}

fn hash_hex(input: &str) -> String {
    format!("{:016x}", fnv1a_64(input.as_bytes()))
}

fn fnv1a_64(input: &[u8]) -> u64 {
    const FNV_OFFSET: u64 = 0xcbf29ce484222325;
    const FNV_PRIME: u64 = 0x00000100000001b3;
    let mut hash = FNV_OFFSET;
    for byte in input {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(FNV_PRIME);
    }
    hash
}

fn truncate_text(value: &str, max_chars: usize) -> String {
    if value.chars().count() <= max_chars {
        return value.to_string();
    }
    let mut out = String::new();
    let keep = max_chars.saturating_sub(3);
    for (idx, ch) in value.chars().enumerate() {
        if idx >= keep {
            break;
        }
        out.push(ch);
    }
    out.push_str("...");
    out
}

